import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"止损的关键点如何判断？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/止损/止损的关键点如何判断.md","filePath":"stock/止损/止损的关键点如何判断.md"}'),r={name:"stock/止损/止损的关键点如何判断.md"};function s(n,t,_,c,i,d){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="止损的关键点如何判断" tabindex="-1">止损的关键点如何判断？ <a class="header-anchor" href="#止损的关键点如何判断" aria-label="Permalink to &quot;止损的关键点如何判断？&quot;">​</a></h1><p>清迈水煮鱼</p><p>&quot;<strong>在顺势行情中赚到钱不叫水平，在震荡行情中控制住亏损才叫水平。”</strong></p><p>这个是我一直奉行的交易原则，也是止损的作用所在。</p><p>A：在刚接触交易的前年，我一直以图形点位逻辑来止损，比如：</p><p>1做多的时候，我在同一周期级别的前低点设置止损。</p><p>2做空的时候，我在同一周期级别的前高点设置止损。</p><p>逻辑非常简单，就是我认为事上涨行情，那么行情如果低于前低点了，这个趋势就很有可能发生改变，那么我就先出来。做空反之。但是很多情况下，都是破了前低点一点点，行情马上又向上走了那么各种懊悔，烦恼，都出来了，为什么命运对我这么不公平，这种情况出现的频率还不少呢，我还固执的认为，是庄家机构故意来收割我这个韭菜的。</p><p>B：交易了一段时间后，我发现一个规律，就是你止损越大，被止损的概率肯定越小，你止损设置得越小，你被止损得概率肯定越大。至于那些做1分钟周期，就设置2-3个点止损的，行情一下出去了，我统计了一下，这根本不是常态，如果一味去追求这种行情，那真的是非常痛苦。<strong>止损不是一个图形逻辑，是一个数学逻辑</strong>。止损的大小，是对市场行情无序波动的容纳程度。 一段时间后，我开始慢慢得放大止损，放大交易级别，这样胜率也慢慢提高了，虽然盈亏比下来了，但我也能接受。</p><p>C：现在阶段我得交易对我来说止损是自己我个人一个很个性化的事情，是我自己能接受多少止损，这个止损不会打破我的内心平衡，哪怕我被止损很多次后，我还是可以一致性得输出我得交易逻辑，而不会因为几次止损后，我去寻找新得方法。对我来说，止损是为了抓住一段行情所付出的成本。我经常问自己，为了这次行情，我付出这次止损，也就是这个成本，我愿意吗？</p><p>我觉得止损设置在哪里不是一个问题的本质，问题的本质是，你能不能接受他，我们的问题是止损设置小了，然后行情被打止损又接着走后我们后悔了，如果止损设置大了，行情没走到我们的预期回去了，我们就后悔止损设置那么大，早知道设置小一点，不就到了我们的盈利目标了嘛。我们的问题是，我们做了选择后，不肯接受这个选择给我带来的不利的一面，我们的问题是我们什么都想要。个人的一点点体会，我是通过这个想法，让我的心保持平衡的，希望对大家都帮助。</p>',11)]))}const f=e(r,[["render",s]]);export{m as __pageData,f as default};
